DmlException same = new DmlException('same');
DmlException other = new DmlException('same');
System.assertEquals(true, same.equals(same));
System.assertEquals(false, same.equals(other));
System.assertEquals(false, same.equals(null));
System.assertEquals(same.hashCode(), same.hashCode());
